package pac;
/** Does not create MMAPI players: hardware playback must be checked on device. */
public final class MusicRoutingTest {
 private static void check(boolean b,String m){if(!b)throw new RuntimeException(m);}
 public static void run(){String[] explore={"ExploreHubScreen","ExploreMapScreen","ExploreBallScreen","ExploreDexScreen","ExploreSummaryScreen","ExploreCatchBattleScreen","WorldScreen","CatchScreen","GachaScreen","SurvivalPickScreen","SurvivalScreen"};for(int i=0;i<explore.length;i++)check(Music.trackFor("pac."+explore[i])==Music.EXPLORE,"explore routing "+explore[i]);String[] chess={"ChessScreen","ChessModeScreen","GenerationModeScreen","GenerationTestScreen","HistoryScreen"};for(int i=0;i<chess.length;i++)check(Music.trackFor("pac."+chess[i])==Music.CHESS,"chess routing");check(Music.trackFor("pac.MenuScreen")==Music.MENU&&Music.trackFor("pac.SettingsScreen")==Music.MENU&&Music.trackFor("pac.StartupNoticeScreen")==Music.MENU,"startup/menu routing");check("/music/autochess.mp3".equals(Music.path(Music.CHESS))&&"/music/explore.mp3".equals(Music.path(Music.EXPLORE))&&"/music/menu.mp3".equals(Music.path(Music.MENU))&&Music.path(0)==null,"music resources");System.out.println("MusicRoutingTest OK: all Explore activities, autochess routes and startup/menu song; not MMAPI playback");}
}
